// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint amount) public {
        vm.assume(amount > 0 && amount <= 1e18);
        uint beforeBalance = address(c).balance;
        uint beforeDeposit = c.balance();
        (bool ok,) = address(c).call{value: amount}(abi.encodeWithSignature("deposit()"));
        require(ok);
        uint afterBalance = address(c).balance;
        uint afterDeposit = c.balance();
        assertTrue(afterBalance == beforeBalance + amount);
        assertTrue(afterDeposit == beforeDeposit + amount);
    }
}

