// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user1, address user2) public {
        vm.assume(user1 != address(0) && user2 != address(0) && user1 != user2);

        vm.deal(user1, 100 ether);
        vm.deal(user2, 100 ether);

        vm.prank(user1);
        c.deposit{value: 1 ether}();
        vm.prank(user2);
        c.deposit{value: 2 ether}();

        // After deposits, the contract's ETH balance should equal sum of all credit balances.
        // Since credit is a public mapping, we can read it via auto-generated getters.
        uint totalCredit = c.credit(user1) + c.credit(user2);
        assertTrue(address(c).balance == totalCredit);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address user, uint amount) public {
        vm.assume(user != address(0));
        amount = bound(amount, 1, 1e18);
        vm.deal(user, amount);
        vm.prank(user);
        c.deposit{value: amount}();
        vm.prank(user);
        c.withdrawAll();
        assertTrue(address(c).balance == 0);
    }
}
